/* test_knh264rtp.c — known-answer tests for kn_h264rtp (slice 5n).
 *
 * Vectors: streamer/src/kn_h264rtp_kat_vectors.h, generated by
 * tools/h264rtp_reference.py — an independent Python implementation of
 * the RFC 6184 depacketizer semantics (single NAL §5.2, STAP-A §5.7.1,
 * FU-A §5.8, int16 sequence discipline, ts-split closes, the
 * broken/over/incomplete gauntlet at the single emit path). The
 * generator's expected AUs are the CONSTRUCTION truth (start codes +
 * source NALs, byte-compared against the reference's own output), its
 * expected counters are hand-labeled per scenario, and its drop-safety
 * pass proves duplicates never perturb the stream and deletions never
 * invent payload. A C/PY disagreement here means one of the two ports
 * drifted from RFC 6184.
 *
 * Scenarios: single, stap_a, fu_a, keyframe_real (the libwebrtc opener
 * STAP-A[SPS,PPS] + FU-A IDR, M on the last fragment), two_frames,
 * ts_split (lost marker), gap_drop (+ orphan E resync), dup_late,
 * fu_incomplete (preempted by a single NAL), oversize (drop whole),
 * seq_wrap (65534..1), malformed (F-bit / truncated STAP-A / 1-byte
 * FU-A + first-bad identity), other_type (30), mixed_stream (mini-GOP).
 *
 * Plus the API edges the vectors can't carry: arg validation, callback
 * abort propagation (marker AND ts-split paths), the buffer-alias
 * contract, idempotent re-init, cap boundary (fits exactly vs one byte
 * over), gap after a clean emit (no phantom drop_gap).
 * Runs on Linux host and Win7 target. */
#include "kn/kn_h264rtp.h"
#include "kn_h264rtp_kat_vectors.h"
#include "test_port.h"

#include <stdio.h>
#include <string.h>

#define TEST_ASM_CAP   8192u           /* largest scenario cap */
#define TEST_AU_SLOTS  16u
#define TEST_AU_BYTES  8192u

static uint8_t  g_asm[TEST_ASM_CAP];   /* assembly buffer under test */
static uint8_t  g_au[TEST_AU_SLOTS][TEST_AU_BYTES];
static uint32_t g_au_ts[TEST_AU_SLOTS];
static unsigned g_au_n;
static unsigned g_au_over;             /* AUs beyond the arena: a bug */

static int collect_cb(const uint8_t *annexb, size_t len, uint32_t rtp_ts,
                      void *ud)
{
    (void)ud;
    if (g_au_n >= TEST_AU_SLOTS || len > TEST_AU_BYTES) {
        ++g_au_over;
        return 0;
    }
    memcpy(g_au[g_au_n], annexb, len);
    g_au_ts[g_au_n] = rtp_ts;
    ++g_au_n;
    return 0;
}

static void arena_reset(void)
{
    g_au_n = 0;
    g_au_over = 0;
}

/* Pack the C stats struct into the vector's counter order. */
static void pack_stats(const kn_h264rtp_stats *s,
                       uint64_t out[K_KAT_H264RTP_NCNTR])
{
    out[0]  = s->pkts_in;       out[1]  = s->pkt_dups;
    out[2]  = s->pkt_gaps;      out[3]  = s->single_nal;
    out[4]  = s->stap_a_pkts;   out[5]  = s->stap_a_nals;
    out[6]  = s->fu_a_pkts;     out[7]  = s->fu_incomplete;
    out[8]  = s->malformed;     out[9]  = s->other_type;
    out[10] = s->aus;           out[11] = s->au_bytes;
    out[12] = s->au_max;        out[13] = s->ts_split;
    out[14] = s->drop_gap;      out[15] = s->drop_broken;
    out[16] = s->drop_over;
}

static void test_scenarios(void)
{
    int s;
    for (s = 0; s < K_KAT_H264RTP_NSCEN; ++s) {
        const k_h264rtp_scen_t *sc = &k_kat_h264rtp_scen[s];
        const k_h264rtp_bad_t *bad = &k_kat_h264rtp_bad[s];
        uint64_t have[K_KAT_H264RTP_NCNTR];
        kn_h264rtp d;
        unsigned k, j, ok;
        int rc = 0;
        char name[128];

        arena_reset();
        kn_h264rtp_init(&d, g_asm, sc->cap);
        for (k = 0; k < sc->npkts && rc == 0; ++k) {
            const k_h264rtp_pkt_t *p = &k_kat_h264rtp_pkts[sc->pkt_off + k];
            rc = kn_h264rtp_push(&d, p->seq, p->ts, p->marker,
                                 k_kat_h264rtp_blob + p->off, p->len,
                                 collect_cb, NULL);
        }

        /* AUs: count, timestamps, bytes — against the construction truth */
        ok = (rc == 0) && (g_au_over == 0) && (g_au_n == sc->naus);
        for (j = 0; ok && j < sc->naus; ++j) {
            const k_h264rtp_au_t *a = &k_kat_h264rtp_aus[sc->au_off + j];
            ok = (g_au_ts[j] == a->ts) &&
                 memcmp(g_au[j], k_kat_h264rtp_blob + a->off, a->len) == 0;
        }
        if (!ok)
            printf("  %s: AU mismatch (%u emitted vs %u expected, rc=%d)\n",
                   sc->name, g_au_n, sc->naus, rc);
        snprintf(name, sizeof name, "%s: %u AUs byte-exact",
                 sc->name, sc->naus);
        CHECK(ok, name);

        /* the full counter face */
        pack_stats(&d.st, have);
        if (memcmp(have, k_kat_h264rtp_counters[s], sizeof have) != 0) {
            for (k = 0; k < K_KAT_H264RTP_NCNTR; ++k)
                if (have[k] != k_kat_h264rtp_counters[s][k])
                    printf("  %s: counter[%u] %llu != %llu\n", sc->name, k,
                           (unsigned long long)have[k],
                           (unsigned long long)k_kat_h264rtp_counters[s][k]);
        }
        snprintf(name, sizeof name, "%s: 17 counters exact", sc->name);
        CHECK(memcmp(have, k_kat_h264rtp_counters[s], sizeof have) == 0,
              name);

        /* first-malformed identity (the flight-log face) */
        ok = ((d.bad_logged != 0) == (bad->logged != 0));
        if (bad->logged)
            ok = ok && d.bad_type == bad->type && d.bad_seq == bad->seq &&
                 d.bad_head_len == bad->head_len &&
                 memcmp(d.bad_head, k_kat_h264rtp_blob + bad->head_off,
                        bad->head_len) == 0;
        snprintf(name, sizeof name, "%s: bad-packet identity", sc->name);
        CHECK(ok, name);
    }
}

static int abort_cb(const uint8_t *annexb, size_t len, uint32_t rtp_ts,
                    void *ud)
{
    (void)annexb; (void)len; (void)rtp_ts; (void)ud;
    return 7;
}

static int alias_cb(const uint8_t *annexb, size_t len, uint32_t rtp_ts,
                    void *ud)
{
    const kn_h264rtp *d = (const kn_h264rtp *)ud;
    (void)len; (void)rtp_ts;
    return (annexb == d->buf) ? 0 : 9;
}

static void test_abort_and_alias(void)
{
    kn_h264rtp d;
    uint8_t nal[48];
    int rc;

    memset(nal, 0xAB, sizeof nal);
    nal[0] = 0x65;                                  /* IDR slice, F=0 */

    /* marker-path abort propagates; the module stays usable after */
    kn_h264rtp_init(&d, g_asm, sizeof g_asm);
    rc = kn_h264rtp_push(&d, 1, 100, 1, nal, sizeof nal, abort_cb, NULL);
    CHECK(rc == 7, "abort: callback rc propagates out of push (marker)");
    arena_reset();
    rc = kn_h264rtp_push(&d, 2, 200, 1, nal, sizeof nal, collect_cb, NULL);
    CHECK(rc == 0 && g_au_n == 1 && g_au_over == 0,
          "abort: next push assembles normally (no sticky module state)");

    /* ts-split-path abort: assemble an UNCLOSED AU (M=0), then a ts
     * change must run the callback on it and propagate its rc */
    arena_reset();
    rc = kn_h264rtp_push(&d, 3, 300, 0, nal, sizeof nal, collect_cb, NULL);
    CHECK(rc == 0 && g_au_n == 0, "abort: M=0 packet assembles without emit");
    rc = kn_h264rtp_push(&d, 4, 400, 0, nal, sizeof nal, abort_cb, NULL);
    CHECK(rc == 7, "abort: rc propagates from the ts-split emit path");

    /* alias contract: the callback pointer IS the assembly buffer */
    kn_h264rtp_init(&d, g_asm, sizeof g_asm);
    rc = kn_h264rtp_push(&d, 1, 100, 1, nal, sizeof nal, alias_cb, &d);
    CHECK(rc == 0, "alias: callback sees the assembly buffer itself");
}

static void test_args(void)
{
    kn_h264rtp d;
    uint8_t nal[8];

    memset(nal, 0x5A, sizeof nal);
    nal[0] = 0x41;                                  /* P slice, F=0 */

    kn_h264rtp_init(NULL, g_asm, sizeof g_asm);     /* must not crash */
    kn_h264rtp_init(&d, g_asm, sizeof g_asm);
    CHECK(kn_h264rtp_push(NULL, 1, 1, 1, nal, sizeof nal,
                          collect_cb, NULL) == -1,
          "args: NULL depacketizer -> -1");
    CHECK(kn_h264rtp_push(&d, 1, 1, 1, NULL, 4, collect_cb, NULL) == -1,
          "args: NULL payload with plen > 0 -> -1");

    /* plen == 0 with payload == NULL is LEGAL: a zero-length RTP payload
     * is malformed on the wire, not an argument error — and must not
     * crash the bad-identity capture (memcpy NULL guard). */
    arena_reset();
    CHECK(kn_h264rtp_push(&d, 1, 1, 1, NULL, 0, collect_cb, NULL) == 0,
          "args: empty payload accepted (rc 0)");
    CHECK(d.st.malformed == 1 && d.bad_logged &&
          d.bad_type == 0xFFFFFFFFu && d.bad_head_len == 0 &&
          g_au_n == 0 && g_au_over == 0,
          "args: empty payload -> malformed + face, silent emit");

    /* NULL assembly buffer: every push refused, no crash */
    kn_h264rtp_init(&d, NULL, 0);
    CHECK(kn_h264rtp_push(&d, 1, 1, 1, nal, sizeof nal,
                          collect_cb, NULL) == -1,
          "args: NULL assembly buffer -> -1");
}

static void test_reinit(void)
{
    /* The malformed scenario run twice through the SAME struct: init
     * must fully reset (counters, bad face, seq/ts state) — the probe
     * re-inits per session without a fresh allocation. */
    const k_h264rtp_scen_t *sc = NULL;
    uint64_t have[K_KAT_H264RTP_NCNTR];
    kn_h264rtp d;
    int s, sidx = -1, pass, ok = 1;

    for (s = 0; s < K_KAT_H264RTP_NSCEN; ++s)
        if (strcmp(k_kat_h264rtp_scen[s].name, "malformed") == 0) {
            sc = &k_kat_h264rtp_scen[s];
            sidx = s;
        }
    if (!sc) { CHECK(0, "reinit: malformed scenario present in vectors"); return; }

    kn_h264rtp_init(&d, g_asm, sc->cap);
    for (pass = 0; pass < 2 && ok; ++pass) {
        unsigned k;
        if (pass == 1) {
            kn_h264rtp_init(&d, g_asm, sc->cap);   /* the reset under test */
            ok = ok && d.bad_logged == 0 && d.st.pkts_in == 0 &&
                 d.have_seq == 0 && d.have_ts == 0;
        }
        for (k = 0; k < sc->npkts; ++k) {
            const k_h264rtp_pkt_t *p = &k_kat_h264rtp_pkts[sc->pkt_off + k];
            arena_reset();
            if (kn_h264rtp_push(&d, p->seq, p->ts, p->marker,
                                k_kat_h264rtp_blob + p->off, p->len,
                                collect_cb, NULL) != 0) ok = 0;
        }
        pack_stats(&d.st, have);
        ok = ok && memcmp(have, k_kat_h264rtp_counters[sidx],
                          sizeof have) == 0;
    }
    CHECK(ok, "reinit: second run on the same struct is identical");
}

static void test_cap_edge(void)
{
    kn_h264rtp d;
    uint8_t nal[40];
    uint8_t fu_s[24], fu_e[24];

    memset(nal, 0xC3, sizeof nal);
    nal[0] = 0x65;                                  /* AU = 4 + 40 = 44 */

    arena_reset();
    kn_h264rtp_init(&d, g_asm, 44);                 /* exact fit */
    kn_h264rtp_push(&d, 1, 100, 1, nal, sizeof nal, collect_cb, NULL);
    CHECK(g_au_n == 1 && d.st.drop_over == 0 && d.st.aus == 1,
          "cap: AU exactly filling the buffer is emitted");

    arena_reset();
    kn_h264rtp_init(&d, g_asm, 43);                 /* one byte short */
    kn_h264rtp_push(&d, 1, 100, 1, nal, sizeof nal, collect_cb, NULL);
    CHECK(g_au_n == 0 && d.st.drop_over == 1 && d.st.aus == 0,
          "cap: AU one byte over is dropped WHOLE (never truncated)");

    /* overflow mid-FU: S fits, E tips it over -> one whole-AU drop and
     * the next frame is clean (au_over must reset at emit). */
    memset(fu_s, 0xD1, sizeof fu_s);
    fu_s[0] = 0x7C; fu_s[1] = 0x85;                 /* FU-A S, type 5 */
    memset(fu_e, 0xD2, sizeof fu_e);
    fu_e[0] = 0x7C; fu_e[1] = 0x45;                 /* FU-A E, type 5 */
    arena_reset();
    kn_h264rtp_init(&d, g_asm, 32);                 /* S: 4+1+22=27 fits */
    kn_h264rtp_push(&d, 1, 100, 0, fu_s, sizeof fu_s, collect_cb, NULL);
    kn_h264rtp_push(&d, 2, 100, 1, fu_e, sizeof fu_e, collect_cb, NULL);
    CHECK(g_au_n == 0 && d.st.drop_over == 1,
          "cap: overflow mid-fragment drops the AU whole");
    kn_h264rtp_push(&d, 3, 200, 1, nal, 20, collect_cb, NULL);
    CHECK(g_au_n == 1 && d.st.aus == 1 && d.st.drop_over == 1,
          "cap: au_over clears at emit — next frame assembles");
}

static void test_gap_after_clean(void)
{
    kn_h264rtp d;
    uint8_t nal[16];

    memset(nal, 0xE7, sizeof nal);
    nal[0] = 0x41;
    arena_reset();
    kn_h264rtp_init(&d, g_asm, sizeof g_asm);
    kn_h264rtp_push(&d, 1, 100, 1, nal, sizeof nal, collect_cb, NULL);
    kn_h264rtp_push(&d, 5, 200, 1, nal, sizeof nal, collect_cb, NULL);
    CHECK(g_au_n == 2 && d.st.pkt_gaps == 1 && d.st.drop_gap == 0 &&
          d.st.aus == 2,
          "gap: after a clean emit the gap drops nothing (no phantom)");
}

int main(void)
{
    test_scenarios();
    test_abort_and_alias();
    test_args();
    test_reinit();
    test_cap_edge();
    test_gap_after_clean();
    return kn_test_summary("test_knh264rtp");
}
